        \item $K$ is of order $\beta$ in the sense that, for some $C_K<\infty$,
        $$|\varphi_K(t) - 1| \leq C_K \min \{1, \|t\|^\beta\}, \qquad t\in \mathbb{R}^d.$$
        \item Its first two derivatives satisfy
        $$\|\nabla K\|_{L^p}<\infty, \qquad \int_{\mathbb{R}^d} \|\nabla^2 K(u) \|_F^p du<\infty, \qquad p\in \{1,2\}.$$
        \item Its third derivative satisfies
        $$\int_{\mathbb{R}^d} \|\nabla^3 K(u)\|_{\rm op}^2 du <\infty,$$
        where $\|\nabla^3 K(u)\|_{\rm op}$ denotes the operator norm of the trilinear form $\nabla^3 K(u)$.

