    } 
        {\csname pseudo@equation\endcsname[0]\relax} 
    \label{eq: modified experiment}
        X_i = \frac1D \Lambda_D^\top Y_i = \eta_i + \underbrace{\frac1D \Lambda_D^\top \epsilon_i}_{\sim N_d(0, \frac1D I_d)}.

